const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const etoshaPan = ee.Geometry.Rectangle([14.24, -19.26, 17.15, -18.42]);
  const startDate = ee.Date('2020-01-01');
  const endDate = ee.Date('2020-01-31');
  const compareStartDate = ee.Date('2020-08-01');
  const compareEndDate = ee.Date('2020-08-31');

  // 2. Data Acquisition
  const collection = ee.ImageCollection("JRC/GSW1_4/MonthlyHistory");

  const imageJan2020 = collection.filterDate(startDate, endDate).first();
  const imageAug2020 = collection.filterDate(compareStartDate, compareEndDate).first();

  // 3. Data Integrity Check (C1)
  // JRC is a single image per month, so check if they exist by trying to get info.
  try {
      imageJan2020.get('system:id').getInfo();
      imageAug2020.get('system:id').getInfo();
  } catch (e) {
      console.log('Error: Could not retrieve one or both monthly images.');
      console.log('A: Yes');
      return;
  }

  // 4. Processing
  // Create a binary mask where water is present (value 2 or 3).
  const waterMaskJan = imageJan2020.select('water').gte(2);
  const waterMaskAug = imageAug2020.select('water').gte(2);

  const scale = 3000; // Use a coarse scale for large area statistics

  // Calculate the area of water for each period.
  // sum() on a binary mask * pixelArea() gives total area.
  const waterAreaJan = waterMaskJan.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: etoshaPan,
    scale: scale,
    maxPixels: 1e9
  });

  const waterAreaAug = waterMaskAug.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: etoshaPan,
    scale: scale,
    maxPixels: 1e9
  });

  // Check for pixel count to avoid C2 error.
  const pixelCountJan = waterMaskJan.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: etoshaPan,
      scale: scale,
      maxPixels: 1e9
  });

  const pixelCountAug = waterMaskAug.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: etoshaPan,
    scale: scale,
    maxPixels: 1e9
  });

  // 5. Validation & Final Answer
  const janResult = waterAreaJan.get('water').getInfo();
  const augResult = waterAreaAug.get('water').getInfo();
  const janPixels = pixelCountJan.get('water').getInfo();
  const augPixels = pixelCountAug.get('water').getInfo();

  if (janPixels === 0 || augPixels === 0) {
      console.log(`Jan 2020 Valid Pixels: ${janPixels}`);
      console.log(`Aug 2020 Valid Pixels: ${augPixels}`);
      console.log('No valid pixels found in the region for one or both periods.');
      console.log('C2');
      return;
  }

  if (janResult === null || augResult === null) {
      console.log('Calculation resulted in null.');
      console.log('C3');
      return;
  }

  // Convert area from square meters to square kilometers for readability
  const janAreaKm2 = janResult / 1e6;
  const augAreaKm2 = augResult / 1e6;

  console.log(`Jan 2020 Water Extent (km²): ${janAreaKm2.toFixed(2)}`);
  console.log(`Aug 2020 Water Extent (km²): ${augAreaKm2.toFixed(2)}`);

  if (augAreaKm2 < janAreaKm2) {
      console.log('A');
  } else {
      console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log('D');
});
